/** How often a live Projects page re-reads its run state. */
export const POLL_INTERVAL_MS = 5000

/**
 * A counter that ticks every `intervalMs` while `active` and the page is visible, and once more as the page becomes
 * visible again; pass it as a resource's `pollToken` to re-read live state in the background.
 */
export function usePoll(active: boolean, intervalMs = POLL_INTERVAL_MS): number {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    if (!active) return
    const next = () => { if (document.visibilityState === 'visible') setTick(previous => previous + 1) }
    const timer = window.setInterval(next, intervalMs)
    document.addEventListener('visibilitychange', next)
    return () => {
      window.clearInterval(timer)
      document.removeEventListener('visibilitychange', next)
    }
  }, [active, intervalMs])
  return tick
}
/**
 * Scrolls a handed-over target (a highlighted task quote, a linked file) into view and keeps it there while the page
 * above it is still loading: results, files and Markdown arrive after the target mounts and would push it away. It stops
 * at the first sign of the reader moving (wheel, touch, key, pointer), after a quiet second without layout changes, or
 * after ten seconds.
 */
const QUIET_MS = 1000
const LIMIT_MS = 10_000
const READER_EVENTS = ['wheel', 'touchstart', 'keydown', 'pointerdown'] as const

export function keepInView(target: Element, options: ScrollIntoViewOptions): () => void {
  const view = target.ownerDocument.defaultView
  if (!view) return () => {}
  let quiet = 0
