191	.markdown { max-width: 80ch; line-height: 1.6; overflow-wrap: anywhere; }
192	.markdown > :first-child { margin-top: 0; }
193	.markdown h1 { font-size: 1.5rem; }
194	.markdown h2 { font-size: 1.25rem; }
195	.markdown h3 { font-size: 1.1rem; }
196	.markdown a { color: var(--accent); }
197	.markdown pre { padding: 12px; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; overflow: auto; font-size: 0.85rem; line-height: 1.5; }
198	.markdown code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.9em; }
199	.markdown :not(pre) > code { background: var(--surface-alt); padding: 1px 4px; border-radius: 3px; }
200	.markdown blockquote { margin: 0; padding-left: 12px; border-left: 3px solid var(--border); color: var(--text-muted); }
201	.markdown .table-wrap { overflow: auto; }
202	.markdown table { border-collapse: collapse; }
203	.markdown th, .markdown td { border: 1px solid var(--border); padding: 4px 8px; text-align: left; vertical-align: top; }
204	.markdown th { background: var(--surface-alt); }
