206	.markdown img.image-unavailable { display: inline-block; min-width: 2em; min-height: 1.4em; padding: 2px 6px; border: 1px dashed var(--border); color: var(--text-muted); font-style: italic; font-size: 0.9em; }
207	.markdown input[type='checkbox'] { margin-right: 6px; }
208	.markdown hr { border: 0; border-top: 1px solid var(--border); }
209	.markdown .link-inert { color: var(--text-muted); text-decoration: underline dotted; cursor: not-allowed; }
210	
211	/* ---- Editing ---- */
212	.document-header-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
213	.document-notice { margin: 0; padding: 8px 16px; color: var(--text-muted); font-size: 0.9rem; border-bottom: 1px solid var(--border); }
214	.document-installed { color: var(--text); background: var(--surface-alt); border-left: 4px solid var(--node-directory-stroke); }
215	.document-location { font-weight: 600; }
