217	.editor { display: flex; flex-direction: column; flex: 1; min-width: 0; }
218	.editor-toolbar { display: flex; align-items: flex-end; justify-content: space-between; gap: 8px; flex-wrap: wrap; border-bottom: 1px solid var(--border); padding-right: 16px; }
219	.editor-toolbar .tabs { border-bottom: none; }
220	.editor-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; padding-bottom: 6px; }
221	.save-status { font-size: 0.85rem; padding: 4px 10px; border-radius: 999px; border: 1px solid var(--border); color: var(--text-muted); min-width: 70px; text-align: center; }
222	.save-status-unsaved { color: var(--text); border-color: var(--focus); }
223	.save-status-saving { color: var(--text); font-style: italic; }
224	.save-status-saved { color: var(--text); }
225	.save-status-error { color: var(--danger-text); background: var(--danger-bg); border-color: var(--danger-border); }
226	.editor-error { margin: 12px 16px 0; }
227	.editor-panel { flex: 1; padding: 16px; min-width: 0; }
228	.editor-host .cm-editor { min-height: 240px; }
229	.editor-host .cm-content, .editor-host .cm-gutter { min-height: 240px; }
230	@media (max-width: 600px) {
231	  .editor-toolbar { padding-right: 8px; }
232	  .editor-panel { padding: 8px; }
233	  .editor-actions { width: 100%; justify-content: flex-end; }
