235	
236	/* ---- Dialogs and recovery ---- */
237	.confirm-dialog { border: 1px solid var(--border); border-radius: 8px; padding: 0; background: var(--surface); color: var(--text); max-width: min(90vw, 480px); }
238	.confirm-dialog::backdrop { background: rgba(0, 0, 0, 0.45); }
239	.confirm-dialog form { padding: 16px; display: flex; flex-direction: column; gap: 12px; }
240	.confirm-dialog h2 { margin: 0; font-size: 1.05rem; }
241	.confirm-description p { margin: 0; }
242	.confirm-description .dialog-path { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; overflow-wrap: anywhere; }
243	.confirm-actions { display: flex; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }
244	.button-danger { border-color: var(--danger-border); color: var(--danger-text); background: var(--danger-bg); }
245	.editor-fallback { margin: 12px 16px 0; display: flex; flex-direction: column; gap: 8px; }
246	.editor-fallback p { margin: 0; }
247	.editor-fallback textarea { width: 100%; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.85rem; color: var(--text); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; padding: 8px; box-sizing: border-box; }
248	
249	/* ---- Operations ---- */
250	.toolbars { display: flex; flex-wrap: wrap; gap: 6px 16px; align-items: center; }
251	.banner { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
252	.banner-info { background: var(--surface-alt); border: 1px solid var(--border); color: var(--text); }
253	.button-small { min-height: 30px; padding: 4px 10px; font-size: 0.8rem; }
254	.field { display: flex; flex-direction: column; gap: 4px; font-size: 0.9rem; }
255	.field input, .field select { font: inherit; color: var(--text); background: var(--surface); border: 1px solid var(--border); border-radius: 6px; padding: 8px; min-height: 36px; }
256	.field input:focus-visible, .field select:focus-visible, .confirm-dialog .button:focus-visible, .editor-fallback textarea:focus-visible {
257	  outline: 3px solid var(--focus);
258	  outline-offset: 2px;
259	}
260	.dialog-error { margin: 0; color: var(--danger-text); }
261	
262	/* ---- Roots navigation (Pi, Claude, Projects) ---- */
263	.roots ul { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px; }
264	.roots a { display: inline-block; color: var(--accent); text-decoration: none; padding: 6px 12px; min-height: 36px; border: 1px solid var(--border); border-radius: 999px; background: var(--surface); }
265	.roots a:hover { background: var(--surface-alt); }
266	.roots a[aria-current='page'] { color: var(--accent-contrast); background: var(--accent); border-color: var(--accent); font-weight: 600; }
267	.roots a:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
268	
269	/* ---- Projects root ---- */
270	/* The Projects root is long-form reading: the page scrolls instead of an inner pane, so nothing is trapped in a small box. */
271	.app-projects { height: auto; min-height: 100%; }
272	.workspace-projects { overflow: visible; flex: 1 0 auto; padding: 16px; }
