274	.workspace-projects h3 { margin: 16px 0 8px; font-size: 1rem; }
275	.workspace-projects h4 { margin: 12px 0 6px; font-size: 0.95rem; }
276	.workspace-projects a { color: var(--accent); }
277	.workspace-projects a:focus-visible, .workspace-projects .button:focus-visible, .workflow-node:focus-visible, .artifact-log:focus-visible {
278	  outline: 3px solid var(--focus);
279	  outline-offset: 2px;
280	}
281	.projects-muted { color: var(--text-muted); font-size: 0.9rem; }
282	.projects-warning { color: var(--danger-text); }
283	.projects-loading { margin: 0; color: var(--text-muted); }
284	.projects-actions { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin: 8px 0 0; }
285	.projects-error { margin: 0 0 12px; padding: 10px 12px; background: var(--danger-bg); border: 1px solid var(--danger-border); color: var(--danger-text); border-radius: 6px; }
286	.projects-error p { margin: 0 0 6px; overflow-wrap: anywhere; }
287	.projects-error p:last-child { margin-bottom: 0; }
288	.projects-error-path code { font-size: 0.85rem; }
289	.projects-error-inline { margin: 0; color: var(--danger-text); overflow-wrap: anywhere; }
290	.projects-empty { padding: 12px; border: 1px dashed var(--border); border-radius: 6px; background: var(--surface-alt); }
291	.projects-empty p { margin: 0 0 6px; }
292	.projects-empty p:last-child { margin-bottom: 0; }
293	.projects-notice { margin: 8px 0; padding: 10px 12px; border: 1px solid var(--node-directory-stroke); background: var(--node-directory-fill); color: var(--text); border-radius: 6px; }
294	.projects-notice p { margin: 0 0 6px; }
295	
296	.projects-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); }
297	.projects-card { display: flex; flex-direction: column; gap: 4px; padding: 10px 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); text-decoration: none; color: var(--text); min-height: 44px; overflow-wrap: anywhere; }
298	.projects-card:hover { background: var(--surface-alt); }
299	.projects-card-title { font-weight: 600; display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
300	.run-list { grid-template-columns: 1fr; }
301	
302	.status-badge { display: inline-flex; align-items: center; gap: 4px; padding: 1px 8px; border-radius: 999px; font-size: 0.8rem; font-weight: 600; border: 1px solid var(--border); background: var(--surface-alt); color: var(--text); white-space: nowrap; }
303	.status-badge::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted); }
304	.status-succeeded::before { background: var(--node-location-stroke); }
305	.status-failed { border-color: var(--danger-border); color: var(--danger-text); background: var(--danger-bg); }
306	.status-failed::before { background: var(--danger-text); }
307	.status-running::before { background: var(--accent); }
308	.status-awaiting_approval, .status-paused { border-color: var(--node-directory-stroke); }
309	.status-awaiting_approval::before, .status-paused::before { background: var(--node-directory-stroke); }
310	.status-cancelled::before { background: var(--text-muted); }
