312	.projects-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 6px 16px; margin: 8px 0; }
313	.projects-facts > div { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
314	.projects-facts dt { font-size: 0.8rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.02em; }
315	.projects-facts dd { margin: 0; overflow-wrap: anywhere; }
316	.projects-facts code, .workspace-projects code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.85em; background: var(--surface-alt); padding: 1px 4px; border-radius: 3px; overflow-wrap: anywhere; }
317	
318	/* Workflow DAG */
