329	.workflow-node-status-bar { fill: var(--text-muted); }
330	.workflow-node.is-succeeded .workflow-node-status-bar { fill: var(--node-location-stroke); }
331	.workflow-node.is-failed .workflow-node-status-bar { fill: var(--danger-text); }
332	.workflow-node.is-failed .workflow-node-shape { stroke: var(--danger-text); fill: var(--danger-bg); }
333	.workflow-node.is-running .workflow-node-status-bar { fill: var(--accent); }
334	.workflow-node.is-awaiting_approval .workflow-node-status-bar, .workflow-node.is-paused .workflow-node-status-bar { fill: var(--node-directory-stroke); }
335	.workflow-node.is-awaiting_approval .workflow-node-shape { stroke: var(--node-directory-stroke); fill: var(--node-directory-fill); stroke-dasharray: 5 3; }
336	.workflow-node.is-pending .workflow-node-shape { stroke-dasharray: 3 3; }
337	.workflow-node.is-definition .workflow-node-status-bar { fill: var(--edge); }
338	.workflow-node.is-selected .workflow-node-shape { stroke: var(--accent); stroke-width: 3; }
339	.workflow-node-focus { fill: none; stroke: var(--focus); stroke-width: 3; stroke-dasharray: 4 3; display: none; }
