350	.live-status { display: inline-flex; align-items: center; gap: 4px; padding: 1px 8px; border-radius: 999px; font-size: 0.8rem; border: 1px solid var(--border); background: var(--surface-alt); color: var(--text-muted); }
351	.live-status-live > [aria-hidden] { color: var(--node-location-stroke); }
