:root {
  color-scheme: light dark;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  line-height: 1.45;

  --bg: #f5f6f8;
  --surface: #ffffff;
  --surface-alt: #eceff3;
  --text: #1c2530;
  --text-muted: #4f5d6b;
  --border: #d3d9e0;
  --accent: #1f5fbf;
  --accent-contrast: #ffffff;
  --focus: #d2610c;
  --danger-bg: #fdecec;
  --danger-border: #e3a3a3;
  --danger-text: #8a1f1f;
  --node-source-fill: #dfe8f7;
  --node-source-stroke: #2c4f85;
  --node-directory-fill: #f5e4b8;
  --node-directory-stroke: #7a5a10;
  --node-file-fill: #ffffff;
  --node-file-stroke: #5b6773;
  --node-location-fill: #dff3e6;
  --node-location-stroke: #2f7a4b;
  --edge: #8a96a3;
  --edge-highlight: #1f5fbf;
  --pin: #b23a48;
  --selection: #cfe0fb;
