export const INPUTS_NONE_SENTENCE = 'Inputs not recorded for this run (the export predates run inputs; re-export it with the workflow CLI).'

export const DECISIONS_NONE_SENTENCE = 'No decisions.md was recorded for this run (its feature predates the guardrails, or the export predates decisions).'

/** The Assignment tab: what the run was asked to do, pinned from its own files, with the feature's decisions and each worker's task rendered as inert Markdown. */
export function AssignmentPanel({ scope, inputs, onRetry, onNavigate, panelId, tabId }: Props) {
  let content: React.ReactNode
  if (inputs.status === 'loading' || inputs.status === 'idle') content = <LoadingPanel>Loading the run inputs…</LoadingPanel>
  else if (inputs.status === 'error') content = <ErrorPanel error={inputs.error} what="The run inputs" onRetry={onRetry} />
  else if (inputs.data === null) content = <p className="projects-muted" data-testid="assignment-inputs-none">{INPUTS_NONE_SENTENCE}</p>
  else {
    const data = inputs.data
    content = (
      <>
        <dl className="projects-facts">
          <div><dt>Feature</dt><dd>{data.feature}</dd></div>
          <div><dt>Source branch</dt><dd>{data.source_branch === null ? 'None recorded' : <code>{data.source_branch}</code>}</dd></div>
          <div><dt>Base commit</dt><dd><code title={data.base_commit}>{shortRevision(data.base_commit)}</code></dd></div>
          <div><dt>Mode</dt><dd>{data.mode}</dd></div>
          {data.automatic && (
            <>
              <div><dt>Deadlines</dt><dd>{deadlinesLabel(data.automatic)}</dd></div>
              <div><dt>Permission mode</dt><dd><code>{data.automatic.permission_mode}</code></dd></div>
              <div><dt>Finish</dt><dd>{data.automatic.finish}</dd></div>
              <div><dt>Reviewer transport</dt><dd data-testid="assignment-reviewer-transport">{data.automatic.reviewer_transport ?? <span className="projects-muted">not pinned (the run predates the setting)</span>}</dd></div>
            </>
          )}
          <div><dt>Attempt cap</dt><dd>{data.max_verification_attempts} per lane and phase</dd></div>
          <div>
            <dt>Lanes</dt>
            <dd data-testid="assignment-lanes">
              <span data-testid="assignment-selected-workers">{data.selected_workers.length === 0 ? 'none recorded' : data.selected_workers.join(', ')}</span>
              {' '}<span className="projects-muted">({data.selected_workers.length} {data.selected_workers.length === 1 ? 'worker lane' : 'worker lanes'} in this run)</span>
              {data.excluded_workers.length > 0 && (
                <> · <span className="projects-muted">declared but not selected: </span><span data-testid="assignment-excluded-workers">{data.excluded_workers.join(', ')}</span></>
              )}
            </dd>
          </div>
        </dl>

        <section className="assignment-decisions" data-testid="assignment-decisions" aria-labelledby="assignment-decisions-title">
          <h4 id="assignment-decisions-title">Decisions</h4>
          {data.decisions === null ? (
            <p className="projects-muted" data-testid="assignment-decisions-none">{DECISIONS_NONE_SENTENCE}</p>

  accepted_at: string | null
  status: RawReviewerStatus
}
export type RawReviewSection = {
  attempt: number
  transport: 'native' | 'print' | 'manual'
  /** `review.json`'s `reviewer`: the one session before 1.4.0, the declared reviewers' sessions joined with ", " from 1.4.0. */
  reviewer_session_id: string
  independent: true
  bundle_sha256: string
  candidate_commit: string
  /** The combined verdict: approved only when every reviewer approved and no reviewer left an unresolved P0/P1. */
  verdict: 'approved' | 'blocked'
  /** The union of every reviewer's findings, each tagged with `reviewer` from 1.4.0; one reviewer's untagged findings before. */
  findings: RawFinding[]
  reviewed_at: string
  diff: { path: 'review.diff'; sha256: string; bytes: number } | null
  /** Export 1.4.0 only, one entry per declared reviewer in declared order; absent before, when the adapter fills one entry named `review`. */
  reviewers?: RawReviewer[]
}
export type RawCheck = { id: string; kind: 'build' | 'typecheck' | 'unit' | 'integration' | 'contract' | 'browser'; argv: string[]; command: string; timeout_seconds: number; scenarios: { id: string; description: string }[] }
export type RawWorkerInput = {
  /** Any label since policy 1.2.0; `frontend` or `backend` before. */
  role: string
  /** Pinned per lane since policy 1.2.0 (export 1.3.0); absent in 1.2.0 exports, whose adapter derives it from the role. */
  required_check_kinds?: RawCheck['kind'][]
  task: string
  prompt: string | null
  owned_paths: string[]
  checks: RawCheck[]
  launch: { session_id: string | null; launch_token: string; launch_requested_at: string; native_started_at: number | null; observed_state: string | null; status: string; launcher_invocations: number; background_id: string | null } | null
  /**
   * Completion 1.1.0 (export 1.5.0) adds the evidence fields and the `question` status; a 1.0.0 completion has neither. Export
   * 1.5.0 also records the version and the text of a question the controller has not recorded (a fourth is served as blocked).
   */
  completion: {
    version?: '1.0.0' | '1.1.0'
    status: 'completed' | 'blocked' | 'question'; summary: string; open_assumptions: string[]
    untested?: string[] | null; falsifying_check?: string | null; verify_yourself?: string | null; question?: string | null
  } | null
  handoff: { summary: string; open_assumptions: string[] } | null
  stop: { stopped: boolean; confirmed_at: string | null } | null
  /** Export 1.5.0: the worker's questions with the operator's answers; absent before. */
  questions?: RawQuestion[]
}
export type RawQuestion = { n: number; question: string; asked_at: string; answer: string | null; answered_at: string | null }
export type RawConcern = { severity: 'P0' | 'P1' | 'P2'; kind: 'assumption' | 'failure_mode' | 'complexity' | 'other'; message: string; consequence: string }
/** Export 1.5.0: the latest `challenge.json` without `run_id` and `version`, plus the number of attempts. */
export type RawChallenge = {
  status: 'passed' | 'paused' | 'accepted' | 'disabled'
  attempt: number
  session_id: string
  pinned: { tasks_sha256: string; decisions_sha256: string; prd_sha256: string | null }
  concerns: RawConcern[]
  simpler_alternative: string
  cheap_experiment: string
  accepted_reason: string | null
  decided_at: string
  attempts: number
}
export type RawInputsSection = {
  feature: string
  policy_version: string
  base_commit: string
  source_branch: string | null
  mode: 'automatic' | 'manual'
  automatic: { finish: string; permission_mode: string; worker_timeout_seconds: number; review_timeout_seconds: number; reviewer_transport: 'native' | 'print' | null } | null
  setup: { argv: string[]; command: string; timeout_seconds: number }[]
  max_verification_attempts: number
  failure_drill: { node_id: string; phase: string; attempt: number } | null
  /** Export 1.3.0 only: the lanes the launch selected (pinned in `plan.workers`) and the declared lanes it left out. */
  selected_workers?: string[]
  excluded_workers?: string[]
  /** Keyed by lane id in policy order; a 1.3.0 export lists the selected lanes only. */
  workers: Record<string, RawWorkerInput>
  /** Export 1.5.0: the pinned `decisions.md` text and the design challenge; absent before. */
  decisions?: string | null
  challenge?: RawChallenge | null
}

/** Receipts store `+00:00` offsets; the adapter normalises them to a trailing Z. */
export const offset = (iso: string) => iso.replace(/Z$/, '+00:00')
const zulu = (value: string) => (value.endsWith('+00:00') ? `${value.slice(0, -6)}Z` : value)

