/**
 * SKELETON (red phase): the run page's Steps model. Types are final; the functions return empty values.
 */
import type { RunDetail } from './api.ts'
import type { AttentionKind, Instant, NodeStatus, RunAttention, Span, Timeline } from '../../contracts/projects/triage.ts'

export type StepRow = {
  node_id: string
  label: string
  kind: RunDetail['definition']['nodes'][number]['kind']
  status: NodeStatus
  shown: NodeStatus
  attempt: number
  spans: Span[]
  start: Instant | null
  end: Instant | null
  ms: number | null
  live: boolean
  inferred: boolean
  marks: string
  outcome: string
  attention: AttentionKind | null
}

export function stepRows(_detail: RunDetail, _timeline: Timeline, _options: { now: number; attention?: RunAttention }): StepRow[] {
  return []
}

export type TimeAxis = { from: number; to: number; position(at: number): number; breaks: { at: number; ms: number }[] }

export function timeAxis(from: number, to: number, _busy: readonly { start: number; end: number }[]): TimeAxis {
  return { from, to, position: () => -1, breaks: [{ at: -1, ms: -1 }] }
}

export function shortStepLabel(node: { node_id: string; label: string }): string {
  return `${node.label}?`
}

export function formatShortSpan(ms: number): string {
  return String(ms)
}

