            const glyph = node.attention ? '?' : status ? STATUS_GLYPH[status] : null
            const className = [
              'workflow-node',
              `workflow-node-${node.kind}`,
              executor === 'agent' ? 'is-agent' : 'is-controller',
              status ? `is-${status}` : 'is-definition',
              node.node_id === selectedId ? 'is-selected' : '',
            ].filter(Boolean).join(' ')
            return (
              <g
                key={node.node_id}
                className={className}
