// TEMPORARY layout probe for S3 (not committed).
import { test, expect } from '@playwright/test'
import { REVIEWERS_WORKFLOW_ID, RUN_REVIEWER_BLOCKED } from './fixtures.ts'
import { RUN_IDENTICAL, UX_RUN_WORKFLOW_ID } from './fixtures/ux-run.ts'
import { installHooks, runUrl } from './support.ts'
installHooks()
const OUT = '/tmp/claude-1000/-home-agentops-dev-md-manager/541817b2-200f-49c5-b924-e4e11cf0112a/scratchpad/s3/shots'
for (const [name, url, w, h] of [
  ['blocked-1440', runUrl(RUN_REVIEWER_BLOCKED, undefined, REVIEWERS_WORKFLOW_ID), 1440, 900],
  ['identical-1440', runUrl(RUN_IDENTICAL, undefined, UX_RUN_WORKFLOW_ID), 1440, 900],
  ['blocked-390', runUrl(RUN_REVIEWER_BLOCKED, undefined, REVIEWERS_WORKFLOW_ID), 390, 844],
] as const) {
  test(`probe ${name}`, async ({ page }) => {
    await page.setViewportSize({ width: w, height: h })
    await page.goto(url)
    await expect(page.getByTestId('run-now')).toHaveAttribute('data-situation', /.+/)
    const boxes: Record<string, unknown> = {}
    for (const [label, selector] of Object.entries({
      header: '.app-header', crumbs: '.navigation', main: 'main', runHeader: '.run-header', line1: '.run-header-line', facts: '.run-facts', now: '[data-testid="run-now"]',
      headline: '.run-now-headline', reason: '.run-now-reason-row', label: '.command-label', steps: '.command-steps', caption: '.command-caption',
      lanes: '[data-testid="run-lanes"]', tabs: '.run-tabs', graph: '.workflow-graph-scroll', legend: '[data-testid="graph-legend"]', thead: '.steps-table thead', firstRow: '.steps-table tbody tr',
    })) {
      const box = await page.locator(selector).first().boundingBox()
      boxes[label] = box ? `${Math.round(box.y)}..${Math.round(box.y + box.height)} (${Math.round(box.height)})` : null
    }
    console.log(name, JSON.stringify(boxes, null, 1))
    await page.screenshot({ path: `${OUT}/${name}.png` })
  })
}
EOF
